// Package gen turns the shared layer into typed Dart and TypeScript (DUALSTACK 5.2).
//
// Every generator adds files to an Output; Output either writes them or, with --check,
// compares them with what is committed.
package gen

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode"
)

// Output collects generated files keyed by repo-relative path.
type Output struct {
	Root  string
	Files map[string][]byte
	// Dirs are fully owned by the generator: on write, files not in Files are removed.
	Dirs []string
}

func NewOutput(root string) *Output { return &Output{Root: root, Files: map[string][]byte{}} }

func (o *Output) Add(path string, content []byte) { o.Files[filepath.ToSlash(path)] = content }

func (o *Output) Own(dir string) { o.Dirs = append(o.Dirs, filepath.ToSlash(dir)) }

// Write writes all files and removes stale files from owned directories.
func (o *Output) Write() error {
	for p, b := range o.Files {
		full := filepath.Join(o.Root, p)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			return err
		}
		if old, err := os.ReadFile(full); err == nil && bytes.Equal(old, b) {
			continue
		}
		if err := os.WriteFile(full, b, 0o644); err != nil {
			return err
		}
	}
	stale, err := o.stale()
	if err != nil {
		return err
	}
	for _, p := range stale {
		if err := os.Remove(filepath.Join(o.Root, p)); err != nil {
			return err
		}
	}
	return nil
}

// Check lists files that differ from the generated content, are missing or are stale.
func (o *Output) Check() ([]string, error) {
	var bad []string
	for p, b := range o.Files {
		old, err := os.ReadFile(filepath.Join(o.Root, p))
		if err != nil {
			bad = append(bad, p+" (missing)")
			continue
		}
		if !bytes.Equal(old, b) {
			bad = append(bad, p+" (differs)")
		}
	}
	stale, err := o.stale()
	if err != nil {
		return nil, err
	}
	for _, p := range stale {
		bad = append(bad, p+" (stale)")
	}
	sort.Strings(bad)
	return bad, nil
}

func (o *Output) stale() ([]string, error) {
	var out []string
	for _, d := range o.Dirs {
		err := filepath.WalkDir(filepath.Join(o.Root, d), func(path string, e os.DirEntry, err error) error {
			if err != nil {
				if os.IsNotExist(err) {
					return nil
				}
				return err
			}
			if e.IsDir() {
				return nil
			}
			rel, _ := filepath.Rel(o.Root, path)
			rel = filepath.ToSlash(rel)
			if _, ok := o.Files[rel]; !ok {
				out = append(out, rel)
			}
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	return out, nil
}

// Header is the first line of every generated source file.
func Header(comment, source string) string {
	return fmt.Sprintf("%s GENERATED by `metro gen` from %s. Do not edit.\n", comment, source)
}

// Camel turns snake_case or kebab-case into camelCase.
func Camel(s string) string {
	parts := strings.FieldsFunc(s, func(r rune) bool { return r == '_' || r == '-' || r == '.' || r == ' ' })
	for i := range parts {
		if i == 0 {
			parts[i] = lowerFirst(parts[i])
		} else {
			parts[i] = upperFirst(parts[i])
		}
	}
	out := strings.Join(parts, "")
	if out != "" && unicode.IsDigit(rune(out[0])) {
		out = "n" + out
	}
	return out
}

// reserved words of Dart and TypeScript that cannot be field names.
var reserved = map[string]bool{"class": true, "default": true, "enum": true, "switch": true, "case": true, "new": true,
	"is": true, "in": true, "var": true, "const": true, "final": true, "this": true, "super": true, "return": true}

// Field is Camel plus an underscore suffix for reserved words (class → class_).
func Field(s string) string {
	c := Camel(s)
	if reserved[c] {
		return c + "_"
	}
	return c
}

// Pascal turns snake_case into PascalCase.
func Pascal(s string) string { return upperFirst(Camel(s)) }

func upperFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}

// Doc formats a comment as Dart/TS doc lines with the given indent.
func Doc(indent, text string) string {
	text = strings.TrimSpace(text)
	if text == "" {
		return ""
	}
	var b strings.Builder
	for _, l := range strings.Split(text, "\n") {
		b.WriteString(indent + "/// " + strings.TrimSpace(l) + "\n")
	}
	return b.String()
}

// TSDoc formats a comment as a JSDoc block.
func TSDoc(indent, text string) string {
	text = strings.TrimSpace(text)
	if text == "" {
		return ""
	}
	lines := strings.Split(text, "\n")
	if len(lines) == 1 {
		return indent + "/** " + strings.TrimSpace(lines[0]) + " */\n"
	}
	var b strings.Builder
	b.WriteString(indent + "/**\n")
	for _, l := range lines {
		b.WriteString(indent + " * " + strings.TrimSpace(l) + "\n")
	}
	b.WriteString(indent + " */\n")
	return b.String()
}
